create schema if not exists seae_private;
revoke all on schema seae_private from public, anon, authenticated;

create table seae.workflow_transitions (
 id uuid primary key default gen_random_uuid(), entity_type text not null check(entity_type in('clearance_case','royalty_batch','settlement_request')), entity_id uuid not null, from_state text, to_state text not null, transition_action text not null, actor_user_id uuid references auth.users(id) on delete set null, actor_reference text, permission_code text references seae.permissions(permission_code), correlation_id text, evidence_reference text, metadata jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now(), created_at timestamptz not null default now());
create table seae.acceptance_tests(test_code text primary key,control_domain text not null,description text not null,severity text not null check(severity in('critical','high','medium','low')),is_active boolean not null default true,created_at timestamptz not null default now());
create table seae.acceptance_test_results(id uuid primary key default gen_random_uuid(),test_code text not null references seae.acceptance_tests(test_code),run_reference text not null,status text not null check(status in('pass','fail','warn')),details jsonb not null default '{}'::jsonb,executed_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(test_code,run_reference));
create table seae.wealth_ecology_impact_links(id uuid primary key default gen_random_uuid(),creator_id uuid references cruds.creators(id),work_id uuid references cruds.works(id),production_id uuid references seae.productions(id),event_id uuid references seae.events(id),cultural_asset_id uuid references seae.cultural_assets(id),revenue_event_id uuid references seae.revenue_events(id),cruds_impact_metric_id uuid references cruds.impact_metrics(id),rgl_wealth_ecology_impact_id uuid references rgl.wealth_ecology_impacts(id),rw_impact_observation_id uuid references rw.impact_observations(id),rw_wealth_yield_record_id uuid references rw.wealth_yield_records(id),linkage_type text not null default 'attribution' check(linkage_type in('attribution','contribution','outcome','verification','yield')),attribution_weight numeric check(attribution_weight is null or attribution_weight between 0 and 1),evidence_reference text,provenance jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(num_nonnulls(creator_id,work_id,production_id,event_id,cultural_asset_id,revenue_event_id)>=1),check(num_nonnulls(cruds_impact_metric_id,rgl_wealth_ecology_impact_id,rw_impact_observation_id,rw_wealth_yield_record_id)>=1));
comment on table seae.wealth_ecology_impact_links is 'Governed attribution bridge from SEAE cultural and economic activity into existing SourceEnergy impact, Wealth Ecology, and wealth-yield records.';

create index seae_workflow_entity_idx on seae.workflow_transitions(entity_type,entity_id); create index seae_workflow_actor_idx on seae.workflow_transitions(actor_user_id); create index seae_workflow_permission_idx on seae.workflow_transitions(permission_code); create index seae_acceptance_results_test_idx on seae.acceptance_test_results(test_code);
create index seae_impact_link_creator_idx on seae.wealth_ecology_impact_links(creator_id); create index seae_impact_link_work_idx on seae.wealth_ecology_impact_links(work_id); create index seae_impact_link_production_idx on seae.wealth_ecology_impact_links(production_id); create index seae_impact_link_event_idx on seae.wealth_ecology_impact_links(event_id); create index seae_impact_link_asset_idx on seae.wealth_ecology_impact_links(cultural_asset_id); create index seae_impact_link_revenue_idx on seae.wealth_ecology_impact_links(revenue_event_id); create index seae_impact_link_cruds_idx on seae.wealth_ecology_impact_links(cruds_impact_metric_id); create index seae_impact_link_rgl_idx on seae.wealth_ecology_impact_links(rgl_wealth_ecology_impact_id); create index seae_impact_link_rw_obs_idx on seae.wealth_ecology_impact_links(rw_impact_observation_id); create index seae_impact_link_rw_yield_idx on seae.wealth_ecology_impact_links(rw_wealth_yield_record_id);
create index if not exists seae_access_memberships_granted_by_idx on seae.access_memberships(granted_by); create index if not exists seae_access_memberships_role_code_idx on seae.access_memberships(role_code); create index if not exists seae_role_permissions_permission_code_idx on seae.role_permissions(permission_code);

alter table seae.workflow_transitions enable row level security; alter table seae.acceptance_tests enable row level security; alter table seae.acceptance_test_results enable row level security; alter table seae.wealth_ecology_impact_links enable row level security;
grant all privileges on seae.workflow_transitions,seae.acceptance_tests,seae.acceptance_test_results,seae.wealth_ecology_impact_links to service_role;
create policy seae_workflow_service_role_all on seae.workflow_transitions for all to service_role using(true) with check(true); create policy seae_acceptance_tests_service_role_all on seae.acceptance_tests for all to service_role using(true) with check(true); create policy seae_acceptance_results_service_role_all on seae.acceptance_test_results for all to service_role using(true) with check(true); create policy seae_impact_links_service_role_all on seae.wealth_ecology_impact_links for all to service_role using(true) with check(true);

create or replace function seae_private.reject_mutation() returns trigger language plpgsql security definer set search_path='' as $$ begin raise exception 'append_only_record'; end $$; revoke all on function seae_private.reject_mutation() from public,anon,authenticated;
drop trigger if exists seae_audit_immutable on seae.audit_events; create trigger seae_audit_immutable before update or delete on seae.audit_events for each row execute function seae_private.reject_mutation(); drop trigger if exists seae_workflow_immutable on seae.workflow_transitions; create trigger seae_workflow_immutable before update or delete on seae.workflow_transitions for each row execute function seae_private.reject_mutation(); drop trigger if exists seae_acceptance_results_immutable on seae.acceptance_test_results; create trigger seae_acceptance_results_immutable before update or delete on seae.acceptance_test_results for each row execute function seae_private.reject_mutation();

create or replace function seae_private.has_permission(p_user uuid,p_permission text,p_organization_oid text default null,p_creator_id uuid default null,p_cultural_authority_id uuid default null) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from seae.access_memberships m join seae.roles r on r.role_code=m.role_code and r.is_active join seae.role_permissions rp on rp.role_code=m.role_code where m.auth_user_id=p_user and rp.permission_code=p_permission and m.assignment_state='ACTIVE' and m.effective_from<=now() and(m.effective_to is null or m.effective_to>now()) and(p_organization_oid is null or m.organization_oid is null or m.organization_oid=p_organization_oid) and(p_creator_id is null or m.creator_id is null or m.creator_id=p_creator_id) and(p_cultural_authority_id is null or m.cultural_authority_id is null or m.cultural_authority_id=p_cultural_authority_id)); $$; revoke all on function seae_private.has_permission(uuid,text,text,uuid,uuid) from public,anon,authenticated;
create or replace function seae_private.write_audit(p_user uuid,p_entity_type text,p_entity_id text,p_action text,p_evidence text default null,p_details jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path='' as $$ declare v_id bigint; begin insert into seae.audit_events(entity_type,entity_id,action,actor_reference,evidence_reference,details) values(p_entity_type,p_entity_id,p_action,coalesce(p_user::text,'system'),p_evidence,coalesce(p_details,'{}'::jsonb)) returning id into v_id; return v_id; end $$; revoke all on function seae_private.write_audit(uuid,text,text,text,text,jsonb) from public,anon,authenticated;
create or replace function seae_private.valid_transition(p_entity_type text,p_from text,p_to text) returns boolean language sql immutable set search_path='' as $$ select case p_entity_type when 'clearance_case' then (p_from,p_to) in(('open','in_review'),('open','withdrawn'),('in_review','blocked'),('in_review','conditionally_cleared'),('in_review','cleared'),('in_review','rejected'),('blocked','in_review'),('conditionally_cleared','in_review'),('conditionally_cleared','cleared'),('conditionally_cleared','rejected'),('open','expired'),('in_review','expired'),('blocked','expired'),('conditionally_cleared','expired')) when 'royalty_batch' then (p_from,p_to) in(('draft','calculated'),('calculated','under_review'),('under_review','approved'),('under_review','rejected'),('approved','submitted_for_settlement'),('submitted_for_settlement','partially_settled'),('submitted_for_settlement','settled'),('partially_settled','settled'),('draft','cancelled'),('calculated','cancelled'),('under_review','cancelled'),('approved','cancelled')) when 'settlement_request' then (p_from,p_to) in(('requested','authorized'),('requested','cancelled'),('requested','disputed'),('authorized','submitted'),('authorized','cancelled'),('authorized','disputed'),('submitted','processing'),('submitted','failed'),('submitted','disputed'),('processing','settled'),('processing','failed'),('processing','disputed'),('failed','submitted'),('disputed','cancelled')) else false end $$; revoke all on function seae_private.valid_transition(text,text,text) from public,anon,authenticated;

create or replace function seae.api_my_access() returns table(role_code text,organization_oid text,creator_id uuid,cultural_authority_id uuid,scope jsonb,effective_from timestamptz,effective_to timestamptz) language sql stable security definer set search_path='' as $$ select m.role_code,m.organization_oid,m.creator_id,m.cultural_authority_id,m.scope,m.effective_from,m.effective_to from seae.access_memberships m where m.auth_user_id=auth.uid() and m.assignment_state='ACTIVE' and m.effective_from<=now() and(m.effective_to is null or m.effective_to>now()) $$; revoke all on function seae.api_my_access() from public,anon; grant execute on function seae.api_my_access() to authenticated,service_role;
create or replace function seae.api_my_permissions() returns table(permission_code text) language sql stable security definer set search_path='' as $$ select distinct rp.permission_code from seae.access_memberships m join seae.role_permissions rp on rp.role_code=m.role_code join seae.roles r on r.role_code=m.role_code and r.is_active where m.auth_user_id=auth.uid() and m.assignment_state='ACTIVE' and m.effective_from<=now() and(m.effective_to is null or m.effective_to>now()) $$; revoke all on function seae.api_my_permissions() from public,anon; grant execute on function seae.api_my_permissions() to authenticated,service_role;
create or replace function seae.api_transition_workflow(p_entity_type text,p_entity_id uuid,p_to_state text,p_evidence_reference text default null,p_correlation_id text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid();v_from text;v_permission text;v_org text;v_before jsonb;v_after jsonb; begin if v_user is null then raise exception 'authentication_required';end if; if p_entity_type='clearance_case' then select status,requesting_organization_oid,to_jsonb(c) into v_from,v_org,v_before from seae.clearance_cases c where id=p_entity_id for update;v_permission:='clearance.decide'; elsif p_entity_type='royalty_batch' then select status,to_jsonb(b) into v_from,v_before from seae.royalty_approval_batches b where id=p_entity_id for update;v_permission:=case when p_to_state in('approved','rejected') then 'royalty.approve' else 'royalty.calculate' end; elsif p_entity_type='settlement_request' then select status,to_jsonb(s) into v_from,v_before from seae.settlement_requests s where id=p_entity_id for update;v_permission:=case when p_to_state='authorized' then 'settlement.authorize' else 'settlement.request' end; else raise exception 'unsupported_entity_type';end if; if v_from is null then raise exception 'entity_not_found';end if; if not seae_private.has_permission(v_user,v_permission,v_org,null,null) then perform seae_private.write_audit(v_user,p_entity_type,p_entity_id::text,'authorization_denied',p_evidence_reference,jsonb_build_object('permission',v_permission,'requested_state',p_to_state,'correlation_id',p_correlation_id));raise exception 'permission_denied';end if; if not seae_private.valid_transition(p_entity_type,v_from,p_to_state) then raise exception 'invalid_state_transition:%->%',v_from,p_to_state;end if; if p_entity_type='clearance_case' then update seae.clearance_cases set status=p_to_state,closed_at=case when p_to_state in('cleared','rejected','withdrawn','expired') then now() else null end,updated_at=now() where id=p_entity_id returning to_jsonb(clearance_cases) into v_after; elsif p_entity_type='royalty_batch' then update seae.royalty_approval_batches set status=p_to_state,approved_by_reference=case when p_to_state='approved' then v_user::text else approved_by_reference end,approved_at=case when p_to_state='approved' then now() else approved_at end,updated_at=now() where id=p_entity_id returning to_jsonb(royalty_approval_batches) into v_after; else update seae.settlement_requests set status=p_to_state,authorized_by_reference=case when p_to_state='authorized' then v_user::text else authorized_by_reference end,authorized_at=case when p_to_state='authorized' then now() else authorized_at end,settled_at=case when p_to_state='settled' then now() else settled_at end,updated_at=now() where id=p_entity_id returning to_jsonb(settlement_requests) into v_after;end if; insert into seae.workflow_transitions(entity_type,entity_id,from_state,to_state,transition_action,actor_user_id,actor_reference,permission_code,correlation_id,evidence_reference,metadata) values(p_entity_type,p_entity_id,v_from,p_to_state,'state_transition',v_user,v_user::text,v_permission,p_correlation_id,p_evidence_reference,jsonb_build_object('before',v_before,'after',v_after)); perform seae_private.write_audit(v_user,p_entity_type,p_entity_id::text,'transition:'||p_to_state,p_evidence_reference,jsonb_build_object('permission',v_permission,'from_state',v_from,'to_state',p_to_state,'correlation_id',p_correlation_id)); return jsonb_build_object('entity_type',p_entity_type,'entity_id',p_entity_id,'from_state',v_from,'to_state',p_to_state,'status','applied'); end $$; revoke all on function seae.api_transition_workflow(text,uuid,text,text,text) from public,anon; grant execute on function seae.api_transition_workflow(text,uuid,text,text,text) to authenticated,service_role;

insert into seae.acceptance_tests(test_code,control_domain,description,severity) values ('E04-AUTH-001','authorization','Raw SEAE tables remain unavailable to authenticated clients; access occurs through governed RPCs.','critical'),('E04-AUTH-002','authorization','RPC derives caller from auth.uid and requires an active role permission.','critical'),('E04-AUDIT-001','audit','Audit events are append-only.','critical'),('E04-WF-001','workflow','Workflow transitions are allow-listed and append an immutable transition record.','critical'),('E04-SETTLE-001','settlement','Settlement request remains a control-plane record and does not itself move funds or tokens.','critical'),('E04-IMPACT-001','wealth_ecology','SEAE activity can link to existing CRUDS, RGL, or RW impact/wealth records with evidence and attribution.','high'),('E04-RLS-001','row_security','Every SEAE table has RLS enabled and at least one policy.','critical') on conflict(test_code) do nothing;
